def _escapify(qstring):
    if isinstance(qstring, text_type):
        qstring = qstring.encode()
    if (not isinstance(qstring, bytearray)):
        qstring = bytearray(qstring)
    text = ''
    for c in qstring:
        packed = struct.pack('!B', c).decode()
        if (packed in __escaped):
            text += ('\\' + packed)
        elif ((c >= 32) and (c < 127)):
            text += packed
        else:
            text += ('\\%03d' % c)
    return text

