def _dpower(xc, xe, yc, ye, p):
    b = (len(str(abs(yc))) + ye)
    lxc = _dlog(xc, xe, ((p + b) + 1))
    shift = (ye - b)
    if (shift >= 0):
        pc = ((lxc * yc) * (10 ** shift))
    else:
        pc = _div_nearest((lxc * yc), (10 ** (- shift)))
    if (pc == 0):
        if (((len(str(xc)) + xe) >= 1) == (yc > 0)):
            (coeff, exp) = (((10 ** (p - 1)) + 1), (1 - p))
        else:
            (coeff, exp) = (((10 ** p) - 1), (- p))
    else:
        (coeff, exp) = _dexp(pc, (- (p + 1)), (p + 1))
        coeff = _div_nearest(coeff, 10)
        exp += 1
    return (coeff, exp)

