def _simplifyconds(expr, s, a):
    from sympy.core.relational import StrictGreaterThan, StrictLessThan, Unequality
    from sympy import Abs
    def power(ex):
        if (ex == s):
            return 1
        if (ex.is_Pow and (ex.base == s)):
            return ex.exp
        return None
    def bigger(ex1, ex2):
        '    Return    True    only    if    |ex1|    >    |ex2|,    False    only    if    |ex1|    <    |ex2|.\n                                                Else    return    None.    '
        if (ex1.has(s) and ex2.has(s)):
            return None
        if (ex1.func is Abs):
            ex1 = ex1.args[0]
        if (ex2.func is Abs):
            ex2 = ex2.args[0]
        if ex1.has(s):
            try:
                return bigger((1 / ex2), (1 / ex1))
            except TypeError:
                return None
        n = power(ex2)
        if (n is None):
            return None
        if ((n > 0) and ((abs(ex1) <= (abs(a) ** n)) == True)):
            return False
        if ((n < 0) and ((abs(ex1) >= (abs(a) ** n)) == True)):
            return True
    def replie(x, y):
        '    simplify    x    <    y    '
        if ((not (x.is_positive or (x.func is Abs))) or (not (y.is_positive or (y.func is Abs)))):
            return (x < y)
        r = bigger(x, y)
        if (r is not None):
            return (not r)
        return (x < y)
    def replue(x, y):
        b = bigger(x, y)
        if ((b == True) or (b == False)):
            return True
        return Unequality(x, y)
    def repl(ex, *args):
        if ((ex == True) or (ex == False)):
            return bool(ex)
        return ex.replace(*args)
    expr = repl(expr, StrictLessThan, replie)
    expr = repl(expr, StrictGreaterThan, (lambda x, y: replie(y, x)))
    expr = repl(expr, Unequality, replue)
    return expr

