def ismount(path):
    try:
        s1 = os.lstat(path)
    except OSError:
        return False
    else:
        if os.path.stat.S_ISLNK(s1.st_mode):
            return False
    parent = os.path.join(path, os.path.pardir)
    parent = os.path.realpath(parent)
    try:
        s2 = os.lstat(parent)
    except OSError:
        return False
    if (s1.st_dev != s2.st_dev):
        return True
    if (s1.st_ino == s2.st_ino):
        return True
    return False

def win_getpass(prompt='Password:    ', stream=None):
    if (sys.stdin is not sys.__stdin__):
        return fallback_getpass(prompt, stream)
    import msvcrt
    for c in prompt:
        msvcrt.putch(c)
    pw = ''
    while 1:
        c = msvcrt.getch()
        if ((c == '\r') or (c == '\n')):
            break
        if (c == '\x03'):
            raise KeyboardInterrupt
        if (c == '\x08'):
            pw = pw[:(-1)]
        else:
            pw = (pw + c)
    msvcrt.putch('\r')
    msvcrt.putch('\n')
    return pw

def parse_unit(size_str, unit=''):
    matches = re.search('^([\\d.]+)([\\w%]+)?$', size_str)
    if (matches is None):
        matches = re.search('^(\\d+),(\\d+),(\\d+)$', size_str)
        if (matches is None):
            module.fail_json(msg=("Error    interpreting    parted    size    output:    '%s'" % size_str))
        size = {'cylinder': int(matches.group(1)), 'head': int(matches.group(2)), 'sector': int(matches.group(3))}
        unit = 'chs'
    else:
        if (matches.group(2) is not None):
            unit = matches.group(2)
        size = float(matches.group(1))
    return (size, unit)

