def pip_version_check(session):
    installed_version = get_installed_version('pip')
    if (installed_version is None):
        return
    pip_version = packaging_version.parse(installed_version)
    pypi_version = None
    try:
        state = load_selfcheck_statefile()
        current_time = datetime.datetime.utcnow()
        if (('last_check' in state.state) and ('pypi_version' in state.state)):
            last_check = datetime.datetime.strptime(state.state['last_check'], SELFCHECK_DATE_FMT)
            if (total_seconds((current_time - last_check)) < (((7 * 24) * 60) * 60)):
                pypi_version = state.state['pypi_version']
        if (pypi_version is None):
            resp = session.get(PyPI.pip_json_url, headers={'Accept': 'application/json'})
            resp.raise_for_status()
            pypi_version = [v for v in sorted(list(resp.json()['releases']), key=packaging_version.parse) if (not packaging_version.parse(v).is_prerelease)][(-1)]
            state.save(pypi_version, current_time)
        remote_version = packaging_version.parse(pypi_version)
        if ((pip_version < remote_version) and (pip_version.base_version != remote_version.base_version)):
            if WINDOWS:
                pip_cmd = 'python    -m    pip'
            else:
                pip_cmd = 'pip'
            logger.warning("You    are    using    pip    version    %s,    however    version    %s    is    available.\nYou    should    consider    upgrading    via    the    '%s    install    --upgrade    pip'    command.", pip_version, pypi_version, pip_cmd)
    except Exception:
        logger.debug('There    was    an    error    checking    the    latest    version    of    pip', exc_info=True)

