def prim_mst_edges(G, minimum, weight='weight', keys=True, data=True, ignore_nan=False):
    is_multigraph = G.is_multigraph()
    push = heappush
    pop = heappop
    nodes = list(G)
    c = count()
    sign = (1 if minimum else (-1))
    while nodes:
        u = nodes.pop(0)
        frontier = []
        visited = [u]
        if is_multigraph:
            for (v, keydict) in G.adj[u].items():
                for (k, d) in keydict.items():
                    wt = (d.get(weight, 1) * sign)
                    if isnan(wt):
                        if ignore_nan:
                            continue
                        msg = 'NaN    found    as    an    edge    weight.    Edge    %s'
                        raise ValueError((msg % ((u, v, k, d),)))
                    push(frontier, (wt, next(c), u, v, k, d))
        else:
            for (v, d) in G.adj[u].items():
                wt = (d.get(weight, 1) * sign)
                if isnan(wt):
                    if ignore_nan:
                        continue
                    msg = 'NaN    found    as    an    edge    weight.    Edge    %s'
                    raise ValueError((msg % ((u, v, d),)))
                push(frontier, (wt, next(c), u, v, d))
        while frontier:
            if is_multigraph:
                (W, _, u, v, k, d) = pop(frontier)
            else:
                (W, _, u, v, d) = pop(frontier)
            if (v in visited):
                continue
            if (is_multigraph and keys):
                if data:
                    (yield (u, v, k, d))
                else:
                    (yield (u, v, k))
            elif data:
                (yield (u, v, d))
            else:
                (yield (u, v))
            visited.append(v)
            nodes.remove(v)
            if is_multigraph:
                for (w, keydict) in G.adj[v].items():
                    if (w in visited):
                        continue
                    for (k2, d2) in keydict.items():
                        new_weight = (d2.get(weight, 1) * sign)
                        push(frontier, (new_weight, next(c), v, w, k2, d2))
            else:
                for (w, d2) in G.adj[v].items():
                    if (w in visited):
                        continue
                    new_weight = (d2.get(weight, 1) * sign)
                    push(frontier, (new_weight, next(c), v, w, d2))

