        if ((d.fieldtype == u'Check') and d.default and (d.default not in (u'0', u'1'))):
            frappe.throw(_(u"Default    for    'Check'    type    of    field    must    be    either    '0'    or    '1'"))
        if ((d.fieldtype == u'Select') and d.default and (d.default not in d.options.split(u'\n'))):
            frappe.throw(_(u'Default    for    {0}    must    be    an    option').format(d.fieldname))
    def check_precision(d):
        if ((d.fieldtype in (u'Currency', u'Float', u'Percent')) and (d.precision is not None) and (not (1 <= cint(d.precision) <= 6))):
            frappe.throw(_(u'Precision    should    be    between    1    and    6'))
    def check_unique_and_text(d):
        if meta.issingle:
            d.unique = 0
            d.search_index = 0
        if getattr(d, u'unique', False):
            if (d.fieldtype not in (u'Data', u'Link', u'Read    Only')):
                frappe.throw(_(u'Fieldtype    {0}    for    {1}    cannot    be    unique').format(d.fieldtype, d.label))
            if (not d.get(u'__islocal')):
                try:
                    has_non_unique_values = frappe.db.sql(u"select    `{fieldname}`,    count(*)\n DCTB  DCTB  DCTB  DCTB  DCTB  DCTB from    `tab{doctype}`    where    ifnull({fieldname},    '')    !=    ''\n DCTB  DCTB  DCTB  DCTB  DCTB  DCTB group    by    `{fieldname}`    having    count(*)    >    1    limit    1".format(doctype=d.parent, fieldname=d.fieldname))
                except MySQLdb.OperationalError as e:
                    if (e.args and (e.args[0] == 1054)):
                        pass
                    else:
                        raise
                else:
                    if (has_non_unique_values and has_non_unique_values[0][0]):
                        frappe.throw(_(u"Field    '{0}'    cannot    be    set    as    Unique    as    it    has    non-unique    values").format(d.label))
        if (d.search_index and (d.fieldtype in (u'Text', u'Long    Text', u'Small    Text', u'Code', u'Text    Editor'))):
            frappe.throw(_(u'Fieldtype    {0}    for    {1}    cannot    be    indexed').format(d.fieldtype, d.label))
    def check_fold(fields):
        fold_exists = False
        for (i, f) in enumerate(fields):
            if (f.fieldtype == u'Fold'):
                if fold_exists:
                    frappe.throw(_(u'There    can    be    only    one    Fold    in    a    form'))
                fold_exists = True
                if (i < (len(fields) - 1)):
                    nxt = fields[(i + 1)]
                    if (nxt.fieldtype != u'Section    Break'):
                        frappe.throw(_(u'Fold    must    come    before    a    Section    Break'))
                else:
                    frappe.throw(_(u'Fold    can    not    be    at    the    end    of    the    form'))
    def check_search_fields(meta):
        u"Throw    exception    if    `search_fields`    don't    contain    valid    fields."
        if (not meta.search_fields):
            return
        for fieldname in (meta.search_fields or u'').split(u','):
            fieldname = fieldname.strip()
            if (fieldname not in fieldname_list):
                frappe.throw(_(u'Search    field    {0}    is    not    valid').format(fieldname))
    def check_title_field(meta):
        u"Throw    exception    if    `title_field`    isn't    a    valid    fieldname."
        if (not meta.get(u'title_field')):
            return
        if (meta.title_field not in fieldname_list):
            frappe.throw(_(u'Title    field    must    be    a    valid    fieldname'), InvalidFieldNameError)
        def _validate_title_field_pattern(pattern):
            if (not pattern):
                return
            for fieldname in re.findall(u'{(.*?)}', pattern, re.UNICODE):
                if fieldname.startswith(u'{'):
                    continue
                if (fieldname not in fieldname_list):
                    frappe.throw(_(u'{{{0}}}    is    not    a    valid    fieldname    pattern.    It    should    be    {{field_name}}.').format(fieldname), InvalidFieldNameError)
        df = meta.get(u'fields', filters={u'fieldname': meta.title_field})[0]
        if df:
            _validate_title_field_pattern(df.options)
            _validate_title_field_pattern(df.default)
    def check_image_field(meta):
        u'check    image_field    exists    and    is    of    type    "Attach    Image"'
        if (not meta.image_field):
            return
        df = meta.get(u'fields', {u'fieldname': meta.image_field})
        if (not df):
            frappe.throw(_(u'Image    field    must    be    a    valid    fieldname'), InvalidFieldNameError)
        if (df[0].fieldtype != u'Attach    Image'):
            frappe.throw(_(u'Image    field    must    be    of    type    Attach    Image'), InvalidFieldNameError)
    def check_is_published_field(meta):
        if (not meta.is_published_field):
            return
        if (meta.is_published_field not in fieldname_list):
            frappe.throw(_(u'Is    Published    Field    must    be    a    valid    fieldname'), InvalidFieldNameError)
    def check_timeline_field(meta):
        if (not meta.timeline_field):
            return
        if (meta.timeline_field not in fieldname_list):
            frappe.throw(_(u'Timeline    field    must    be    a    valid    fieldname'), InvalidFieldNameError)
        df = meta.get(u'fields', {u'fieldname': meta.timeline_field})[0]
        if (df.fieldtype not in (u'Link', u'Dynamic    Link')):
            frappe.throw(_(u'Timeline    field    must    be    a    Link    or    Dynamic    Link'), InvalidFieldNameError)
    def check_sort_field(meta):
        u'Validate    that    sort_field(s)    is    a    valid    field'
        if meta.sort_field:
            sort_fields = [meta.sort_field]
            if (u',' in meta.sort_field):
                sort_fields = [d.split()[0] for d in meta.sort_field.split(u',')]
            for fieldname in sort_fields:
                if (not (fieldname in (fieldname_list + list(default_fields)))):
                    frappe.throw(_(u'Sort    field    {0}    must    be    a    valid    fieldname').format(fieldname), InvalidFieldNameError)
    fields = meta.get(u'fields')
    fieldname_list = [d.fieldname for d in fields]
    not_allowed_in_list_view = list(copy.copy(no_value_fields))
    not_allowed_in_list_view.append(u'Attach    Image')
    if meta.istable:
        not_allowed_in_list_view.remove(u'Button')
    for d in fields:
        if (not d.permlevel):
            d.permlevel = 0
        if (d.fieldtype != u'Table'):
            d.allow_bulk_edit = 0
        if (not d.fieldname):
            frappe.throw(_(u'Fieldname    is    required    in    row    {0}').format(d.idx))
        d.fieldname = d.fieldname.lower()
        check_illegal_characters(d.fieldname)
        check_unique_fieldname(d.fieldname)
        check_fieldname_length(d.fieldname)
        check_illegal_mandatory(d)
        check_link_table_options(d)
        check_dynamic_link_options(d)
        check_hidden_and_mandatory(d)
        check_in_list_view(d)
        check_in_global_search(d)
        check_illegal_default(d)
        check_unique_and_text(d)
    check_fold(fields)
    check_search_fields(meta)
    check_title_field(meta)
    check_timeline_field(meta)
    check_is_published_field(meta)
    check_sort_field(meta)

