            (mod_name, loader, code, fname) = _get_module_details(mod_name)
        else:
            (mod_name, loader, code, fname) = _get_main_module_details()
    except ImportError as exc:
        msg = ('%s:    %s' % (sys.executable, str(exc)))
        sys.exit(msg)
    pkg_name = mod_name.rpartition('.')[0]
