def tailLines(filename, linesback):
    avgcharsperline = 150
    file = open(filename, 'r')
    while 1:
        try:
            file.seek((((-1) * avgcharsperline) * linesback), 2)
        except IOError:
            file.seek(0)
        if (file.tell() == 0):
            atstart = 1
        else:
            atstart = 0
        lines = file.read().split('\n')
        if ((len(lines) > (linesback + 1)) or atstart):
            break
        avgcharsperline = (avgcharsperline * 1.3)
    file.close()
    if (len(lines) > linesback):
        start = ((len(lines) - linesback) - 1)
    else:
        start = 0
    return lines[start:(len(lines) - 1)]

def serve(request, path, document_root=None, show_indexes=False):
    path = posixpath.normpath(urllib.unquote(path))
    path = path.lstrip('/')
    newpath = ''
    for part in path.split('/'):
        if (not part):
            continue
        (drive, part) = os.path.splitdrive(part)
        (head, part) = os.path.split(part)
        if (part in (os.curdir, os.pardir)):
            continue
        newpath = os.path.join(newpath, part).replace('\\', '/')
    if (newpath and (path != newpath)):
        return HttpResponseRedirect(newpath)
    fullpath = os.path.join(document_root, newpath)
    if os.path.isdir(fullpath):
        if show_indexes:
            return directory_index(newpath, fullpath)
        raise Http404('Directory    indexes    are    not    allowed    here.')
    if (not os.path.exists(fullpath)):
        raise Http404(('"%s"    does    not    exist' % fullpath))
    statobj = os.stat(fullpath)
    (mimetype, encoding) = mimetypes.guess_type(fullpath)
    mimetype = (mimetype or 'application/octet-stream')
    if (not was_modified_since(request.META.get('HTTP_IF_MODIFIED_SINCE'), statobj[stat.ST_MTIME], statobj[stat.ST_SIZE])):
        return HttpResponseNotModified(mimetype=mimetype)
    contents = open(fullpath, 'rb').read()
    response = HttpResponse(contents, mimetype=mimetype)
    response['Last-Modified'] = http_date(statobj[stat.ST_MTIME])
    response['Content-Length'] = len(contents)
    if encoding:
        response['Content-Encoding'] = encoding
    return response

def unitvec(vec, norm='l2'):
    if (norm not in ('l1', 'l2')):
        raise ValueError(("'%s'    is    not    a    supported    norm.    Currently    supported    norms    are    'l1'    and    'l2'." % norm))
    if scipy.sparse.issparse(vec):
        vec = vec.tocsr()
        if (norm == 'l1'):
            veclen = np.sum(np.abs(vec.data))
        if (norm == 'l2'):
            veclen = np.sqrt(np.sum((vec.data ** 2)))
        if (veclen > 0.0):
            return (vec / veclen)
        else:
            return vec
    if isinstance(vec, np.ndarray):
        vec = np.asarray(vec, dtype=float)
        if (norm == 'l1'):
            veclen = np.sum(np.abs(vec))
        if (norm == 'l2'):
            veclen = blas_nrm2(vec)
        if (veclen > 0.0):
            return blas_scal((1.0 / veclen), vec)
        else:
            return vec
    try:
        first = next(iter(vec))
    except:
        return vec
    if (isinstance(first, (tuple, list)) and (len(first) == 2)):
        if (norm == 'l1'):
            length = float(sum((abs(val) for (_, val) in vec)))
        if (norm == 'l2'):
            length = (1.0 * math.sqrt(sum(((val ** 2) for (_, val) in vec))))
        assert (length > 0.0), 'sparse    documents    must    not    contain    any    explicit    zero    entries'
        return ret_normalized_vec(vec, length)
    else:
        raise ValueError('unknown    input    type')

