def xtext_decode(s, errors=None):
    r = []
    i = 0
    while (i < len(s)):
        if (s[i] == '+'):
            try:
                r.append(chr(int(s[(i + 1):(i + 3)], 16)))
            except ValueError:
                r.append(s[i:(i + 3)])
            i += 3
        else:
            r.append(s[i])
            i += 1
    return (''.join(r), len(s))

def searchupwards(start, files=[], dirs=[]):
    start = os.path.abspath(start)
    parents = start.split(os.sep)
    exists = os.path.exists
    join = os.sep.join
    isdir = os.path.isdir
    while len(parents):
        candidate = (join(parents) + os.sep)
        allpresent = 1
        for f in files:
            if (not exists(('%s%s' % (candidate, f)))):
                allpresent = 0
                break
        if allpresent:
            for d in dirs:
                if (not isdir(('%s%s' % (candidate, d)))):
                    allpresent = 0
                    break
        if allpresent:
            return candidate
        parents.pop((-1))
    return None

def _populate_var_to_app_to_idx(outputs, wrt, consider_constant):
    if (consider_constant is None):
        consider_constant = []
    else:
        try:
            iter(consider_constant)
        except TypeError:
            raise TypeError(('consider_constant    must    be    an    iterable    collection,    got    ' + str(type(consider_constant))))
        for elem in consider_constant:
            if (not isinstance(elem, gof.Variable)):
                raise TypeError(('Elements    of    consider_constant    must    be    variables,    but    got    ' + str(type(elem))))
    var_to_app_to_idx = OrderedDict()
    accounted_for = set([])
    def account_for(var):
        if (var in accounted_for):
            return
        accounted_for.add(var)
        if (var in consider_constant):
            return
        if (var.owner is not None):
            app = var.owner
            connection_pattern = _node_to_pattern(app)
            var_idx = app.outputs.index(var)
            for (i, ipt) in enumerate(app.inputs):
                if (not connection_pattern[i][var_idx]):
                    continue
                if (ipt not in var_to_app_to_idx):
                    var_to_app_to_idx[ipt] = OrderedDict()
                app_to_idx = var_to_app_to_idx[ipt]
                if (app not in app_to_idx):
                    app_to_idx[app] = []
                idx = app_to_idx[app]
                if (i not in idx):
                    idx.append(i)
                account_for(ipt)
    for output in outputs:
        account_for(output)
    visited = set([])
    def visit(var):
        if (var in visited):
            return
        if (var not in var_to_app_to_idx):
            return
        visited.add(var)
        nodes = var_to_app_to_idx[var]
        for node in nodes:
            connection_pattern = _node_to_pattern(node)
            for idx in nodes[node]:
                for (ii, output) in enumerate(node.outputs):
                    if connection_pattern[idx][ii]:
                        visit(output)
    for elem in wrt:
        visit(elem)
    orig_vars = list(var_to_app_to_idx.keys())
    for var in orig_vars:
        if (var not in visited):
            del var_to_app_to_idx[var]
    return var_to_app_to_idx

