def _sqrt_ratcomb(cs, args):
    from sympy.simplify.radsimp import radsimp
    def find(a):
        n = len(a)
        for i in range((n - 1)):
            for j in range((i + 1), n):
                s1 = a[i].base
                s2 = a[j].base
                p = _mexpand((s1 * s2))
                s = sqrtdenest(sqrt(p))
                if (s != sqrt(p)):
                    return (s, i, j)
    indices = find(args)
    if (indices is None):
        return Add(*[(c * arg) for (c, arg) in zip(cs, args)])
    (s, i1, i2) = indices
    c2 = cs.pop(i2)
    args.pop(i2)
