def pool_2d(input, ws=None, ignore_border=None, stride=None, pad=(0, 0), mode='max', ds=None, st=None, padding=None):
    if (ds is not None):
        if (ws is not None):
            raise ValueError("You    can't    provide    a    tuple    value    to    both    'ws'    and    'ds'.    Please    provide    a    value    only    to    'ws'.")
        else:
            warnings.warn("DEPRECATION:    the    'ds'    parameter    is    not    going    to    exist    anymore    as    it    is    going    to    be    replaced    by    the    parameter    'ws'.", stacklevel=2)
            ws = ds
    elif ((ds is None) and (ws is None)):
        raise ValueError('You    must    provide    a    tuple    value    for    the    window    size.')
    if (st is not None):
        if (stride is not None):
            raise ValueError("You    can't    provide    a    tuple    value    to    both    'st    and    'stride'.    Please    provide    a    value    only    to    'stride'.")
        else:
            warnings.warn("DEPRECATION:    the    'st'    parameter    is    not    going    to    exist    anymore    as    it    is    going    to    be    replaced    by    the    parameter    'stride'.", stacklevel=2)
            stride = st
    if (padding is not None):
        if (pad not in {None, (0, 0)}):
            raise ValueError("You    can't    provide    a    tuple    value    to    both    'padding'    and    pad.        Please    provide    a    value    only    to    pad.")
        else:
            warnings.warn("DEPRECATION:    the    'padding'    parameter    is    not    going    to    exist    anymore    as    it    is    going    to    be    replaced    by    the    parameter    'pad'.", stacklevel=2)
            pad = padding
    if (input.ndim < 2):
        raise NotImplementedError('pool_2d    requires    a    dimension    >=    2')
    if (ignore_border is None):
        warnings.warn("pool_2d()    will    have    the    parameter    ignore_border    default    value    changed    to    True    (currently    False).    To    have    consistent    behavior    with    all    Theano    version,    explicitly    add    the    parameter    ignore_border=True.    On    the    GPU,    using    ignore_border=True    is    needed    to    use    cuDNN.    When    using    ignore_border=False    and    not    using    cuDNN,    the    only    GPU    combination    supported    is    when    `ws    ==    stride    and    pad    ==    (0,    0)    and    mode    ==    'max'`.    Otherwise,    the    convolution    will    be    executed    on    CPU.", stacklevel=2)
        ignore_border = False
    op = Pool(ignore_border, ndim=2, mode=mode)
    output = op(input, ws, stride, pad)
    return output

