def remove_dups_and_excl(merge_file, exclusion_regexes):
    number_of_rules = settings[u'numberofrules']
    if os.path.isfile(settings[u'whitelistfile']):
        with open(settings[u'whitelistfile'], u'r') as ins:
            for line in ins:
                line = line.strip(u'     DCTB \n\r')
                if (line and (not line.startswith(u'#'))):
                    settings[u'exclusions'].append(line)
    if (not os.path.exists(settings[u'outputpath'])):
        os.makedirs(settings[u'outputpath'])
    final_file = open(path_join_robust(settings[u'outputpath'], u'hosts'), (u'w+b' if PY3 else u'w+'))
    merge_file.seek(0)
    hostnames = {u'localhost', u'localhost.localdomain', u'local', u'broadcasthost'}
    exclusions = settings[u'exclusions']
    for line in merge_file.readlines():
        write_line = True
        line = line.decode(u'UTF-8')
        line = line.replace(u' DCTB +', u'    ')
        line = (line.rstrip(u'    .') + u'\n')
        if ((line[0] == u'#') or re.match(u'^\\s*$', line[0])):
            write_data(final_file, line)
            continue
        if (u'::1' in line):
            continue
        stripped_rule = strip_rule(line)
        if ((not stripped_rule) or matches_exclusions(stripped_rule, exclusion_regexes)):
            continue
        (hostname, normalized_rule) = normalize_rule(stripped_rule, target_ip=settings[u'targetip'], keep_domain_comments=settings[u'keepdomaincomments'])
        for exclude in exclusions:
            if re.search(((u'[\\s\\.]' + re.escape(exclude)) + u'\\s'), line):
                write_line = False
                break
        if (normalized_rule and (hostname not in hostnames) and write_line):
            write_data(final_file, normalized_rule)
