def _CopyDocumentToProtocolBuffer(document, pb):
    pb.set_storage(document_pb.Document.DISK)
    if document.doc_id:
        pb.set_id(document.doc_id.encode('utf-8'))
    if document.language:
        pb.set_language(document.language.encode('utf-8'))
    for field in document.fields:
        field_pb = pb.add_field()
        _CopyFieldToProtocolBuffer(field, field_pb)
    for facet in document.facets:
        facet_pb = pb.add_facet()
        facet._CopyToProtocolBuffer(facet_pb)
    pb.set_order_id(document.rank)
    return pb

def format_date(dt, format, assume_utc=False, as_utc=False):
    if (not format):
        format = 'dd    MMM    yyyy'
    if (not isinstance(dt, datetime)):
        dt = datetime.combine(dt, time())
    if hasattr(dt, 'tzinfo'):
        if (dt.tzinfo is None):
            dt = dt.replace(tzinfo=(_utc_tz if assume_utc else _local_tz))
        dt = dt.astimezone((_utc_tz if as_utc else _local_tz))
    if (format == 'iso'):
        return isoformat(dt, assume_utc=assume_utc, as_utc=as_utc)
    if (dt == UNDEFINED_DATE):
        return ''
    strf = partial(strftime, t=dt.timetuple())
    repl_func = partial(fd_repl_func, dt, strf, ('ap' in format.lower()))
    return re.sub('(s{1,2})|(m{1,2})|(h{1,2})|(ap)|(AP)|(d{1,4}|M{1,4}|(?:yyyy|yy))', repl_func, format)

