def total_ordering(cls):
    convert = {'__lt__': [('__gt__', (lambda self, other: (not ((self < other) or (self == other))))), ('__le__', (lambda self, other: ((self < other) or (self == other)))), ('__ge__', (lambda self, other: (not (self < other))))], '__le__': [('__ge__', (lambda self, other: ((not (self <= other)) or (self == other)))), ('__lt__', (lambda self, other: ((self <= other) and (not (self == other))))), ('__gt__', (lambda self, other: (not (self <= other))))], '__gt__': [('__lt__', (lambda self, other: (not ((self > other) or (self == other))))), ('__ge__', (lambda self, other: ((self > other) or (self == other)))), ('__le__', (lambda self, other: (not (self > other))))], '__ge__': [('__le__', (lambda self, other: ((not (self >= other)) or (self == other)))), ('__gt__', (lambda self, other: ((self >= other) and (not (self == other))))), ('__lt__', (lambda self, other: (not (self >= other))))]}
    roots = (set(dir(cls)) & set(convert))
    if (not roots):
        raise ValueError('must    define    at    least    one    ordering    operation:    <    >    <=    >=')
    root = max(roots)
    for (opname, opfunc) in convert[root]:
        if (opname not in roots):
            opfunc.__name__ = opname
            opfunc.__doc__ = getattr(int, opname).__doc__
            setattr(cls, opname, opfunc)
    return cls

def DefineFromProtobuf(cls, protobuf):
    cls.recorded_rdf_deps = set()
    message_options = protobuf.DESCRIPTOR.GetOptions()
    semantic_options = message_options.Extensions[semantic_pb2.semantic]
    classes_dict = type_info.TypeInfoObject.classes
    if (semantic_options.description and (not cls.__doc__)):
        cls.__doc__ = semantic_options.description
    cls.union_field = (semantic_options.union_field or None)
    for field in protobuf.DESCRIPTOR.fields:
        type_descriptor = None
        options = field.GetOptions().Extensions[semantic_pb2.sem_type]
        kwargs = dict(description=options.description, name=field.name, friendly_name=options.friendly_name, field_number=field.number, labels=list(options.label))
        if field.has_default_value:
            kwargs['default'] = field.default_value
        if (options.type and (field.type != TYPE_MESSAGE)):
            cls.recorded_rdf_deps.add(options.type)
            rdf_type = getattr(rdfvalue, options.type, None)
            if rdf_type:
                if (CHECK_PROTOBUF_DEPENDENCIES and (rdf_type not in cls.rdf_deps) and (options.type not in cls.rdf_deps)):
                    raise rdfvalue.InitializeError(('%s.%s:    field    %s    is    of    type    %s,    but    type    is    missing    from    its    dependencies    list' % (cls.__module__, cls.__name__, field.name, options.type)))
                required_field_type = _SEMANTIC_PRIMITIVE_TO_FIELD_TYPE[rdf_type.data_store_type]
                if (required_field_type != field.type):
                    raise rdfvalue.InitializeError(('%s:    .proto    file    uses    incorrect    field    to    store    Semantic    Value    %s:    Should    be    %s' % (cls.__name__, field.name, rdf_type.data_store_type)))
            type_descriptor = classes_dict['ProtoRDFValue'](rdf_type=options.type, **kwargs)
        elif (options.type and (field.type == TYPE_MESSAGE)):
            raise rdfvalue.InitializeError(('%s:    .proto    file    specified    both    Semantic    Value    type    %s    and    Semantic    protobuf    %s' % (cls.__name__, options.type, field.message_type.name)))
        elif (field.type == TYPE_DOUBLE):
            type_descriptor = classes_dict['ProtoDouble'](**kwargs)
        elif (field.type == TYPE_FLOAT):
            type_descriptor = classes_dict['ProtoFloat'](**kwargs)
        elif (field.type == TYPE_BOOL):
            type_descriptor = classes_dict['ProtoBoolean'](**kwargs)
        elif (field.type == TYPE_STRING):
            type_descriptor = classes_dict['ProtoString'](**kwargs)
        elif (field.type == TYPE_BYTES):
            type_descriptor = classes_dict['ProtoBinary'](**kwargs)
            if options.dynamic_type:
                dynamic_cb = getattr(cls, options.dynamic_type, None)
                if (dynamic_cb is not None):
                    type_descriptor = classes_dict['ProtoDynamicEmbedded'](dynamic_cb=dynamic_cb, **kwargs)
                else:
                    logging.warning('Dynamic    type    specifies    a    non    existant    callback    %s', options.dynamic_type)
        elif ((field.type == TYPE_MESSAGE) and options.dynamic_type and (field.message_type.name == 'Any')):
            dynamic_cb = getattr(cls, options.dynamic_type, None)
            if (dynamic_cb is not None):
                type_descriptor = classes_dict['ProtoDynamicAnyValueEmbedded'](dynamic_cb=dynamic_cb, **kwargs)
            else:
                logging.warning('Dynamic    type    specifies    a    non    existant    AnyValue    callback    %s', options.dynamic_type)
        elif ((field.type == TYPE_INT64) or (field.type == TYPE_INT32)):
            type_descriptor = classes_dict['ProtoSignedInteger'](**kwargs)
        elif ((field.type == TYPE_UINT32) or (field.type == TYPE_UINT64)):
            type_descriptor = classes_dict['ProtoUnsignedInteger'](**kwargs)
        elif ((field.type == TYPE_MESSAGE) and field.message_type):
            type_descriptor = classes_dict['ProtoEmbedded'](nested=field.message_type.name, **kwargs)
            cls.recorded_rdf_deps.add(field.message_type.name)
            if CHECK_PROTOBUF_DEPENDENCIES:
                found = False
                for d in cls.rdf_deps:
                    if ((hasattr(d, '__name__') and (d.__name__ == field.message_type.name)) or (d == field.message_type.name)):
                        found = True
                if (not found):
                    raise rdfvalue.InitializeError(('%s.%s:    TYPE_MESSAGE    field    %s    is    %s,    but    type    is    missing    from    its    dependencies    list' % (cls.__module__, cls.__name__, field.name, field.message_type.name)))
            if type_descriptor.type:
                semantic_protobuf_primitive = type_descriptor.type.protobuf.__name__
                if (semantic_protobuf_primitive != field.message_type.name):
                    raise rdfvalue.InitializeError(('%s.%s:    Conflicting    primitive    (%s)    and    semantic    protobuf    %s    which    implements    primitive    protobuf    (%s)' % (cls.__name__, field.name, field.message_type.name, type_descriptor.type.__name__, semantic_protobuf_primitive)))
        elif field.enum_type:
            enum_desc = field.enum_type
            enum_dict = {}
            enum_descriptions = {}
            enum_labels = {}
            for enum_value in enum_desc.values:
                enum_dict[enum_value.name] = enum_value.number
                description = enum_value.GetOptions().Extensions[semantic_pb2.description]
                enum_descriptions[enum_value.name] = description
                labels = [label for label in enum_value.GetOptions().Extensions[semantic_pb2.label]]
                enum_labels[enum_value.name] = labels
            enum_dict = dict(((x.name, x.number) for x in enum_desc.values))
            type_descriptor = classes_dict['ProtoEnum'](enum_name=enum_desc.name, enum=enum_dict, enum_descriptions=enum_descriptions, enum_labels=enum_labels, **kwargs)
            setattr(cls, enum_desc.name, type_descriptor.enum_container)
        if (type_descriptor is not None):
            if (field.label == LABEL_REPEATED):
                options = field.GetOptions().Extensions[semantic_pb2.sem_type]
                type_descriptor = classes_dict['ProtoList'](type_descriptor, labels=list(options.label))
            try:
                cls.AddDescriptor(type_descriptor)
            except Exception:
                logging.error('Failed    to    parse    protobuf    %s', cls)
                raise
        else:
            logging.error('Unknown    field    type    for    %s    -    Ignoring.', field.name)

def uncompyle(version, co, out=None, showasm=0, showast=0, deob=0):
    assert (type(co) == types.CodeType)
    __real_out = (out or sys.stdout)
    if co.co_filename:
        print >>__real_out, ('#Embedded    file    name:    %s' % co.co_filename)
    scanner = Scanner.getscanner(version)
    scanner.setShowAsm(showasm, out)
    (tokens, customize) = scanner.disassemble(co, deob=deob)
    walker = Walker.Walker(out, scanner, showast=showast)
    try:
        ast = walker.build_ast(tokens, customize)
    except Walker.ParserError as e:
        print >>__real_out, e
        raise
    del tokens
    assert (ast == 'stmts')
    try:
        if (ast[0][0] == Walker.ASSIGN_DOC_STRING(co.co_consts[0])):
            walker.print_docstring('', co.co_consts[0])
            del ast[0]
        if (ast[(-1)] == Walker.RETURN_NONE):
            ast.pop()
    except:
        pass
    walker.mod_globs = Walker.find_globals(ast, set())
    walker.gen_source(ast, customize)
    for g in walker.mod_globs:
        walker.write(('global    %s    ##    Warning:    Unused    global\n' % g))
    if walker.pending_newlines:
        print >>__real_out
    if walker.ERROR:
        raise walker.ERROR

def PutAsync(entities, **kwargs):
    extra_hook = kwargs.pop('extra_hook', None)
    config = _GetConfigFromKwargs(kwargs)
    if (getattr(config, 'read_policy', None) == EVENTUAL_CONSISTENCY):
        raise datastore_errors.BadRequestError('read_policy    is    only    supported    on    read    operations.')
    (entities, multiple) = NormalizeAndTypeCheck(entities, Entity)
    for entity in entities:
        if entity.is_projection():
            raise datastore_errors.BadRequestError(('Cannot    put    a    partial    entity:    %s' % entity))
        if ((not entity.kind()) or (not entity.app())):
            raise datastore_errors.BadRequestError(('App    and    kind    must    not    be    empty,    in    entity:    %s' % entity))
    def local_extra_hook(keys):
        num_keys = len(keys)
        num_entities = len(entities)
        if (num_keys != num_entities):
            raise datastore_errors.InternalError(('Put    accepted    %d    entities    but    returned    %d    keys.' % (num_entities, num_keys)))
        for (entity, key) in zip(entities, keys):
            if (entity._Entity__key._Key__reference != key._Key__reference):
                assert (not entity._Entity__key.has_id_or_name())
                entity._Entity__key._Key__reference.CopyFrom(key._Key__reference)
        if multiple:
            result = keys
        else:
            result = keys[0]
        if extra_hook:
            return extra_hook(result)
        return result
    return _GetConnection().async_put(config, entities, local_extra_hook)

