def nlargest(n, iterable):
    if (n < 0):
        return []
    it = iter(iterable)
    result = list(islice(it, n))
    if (not result):
        return result
    heapify(result)
    _heappushpop = heappushpop
    for elem in it:
        _heappushpop(result, elem)
    result.sort(reverse=True)
    return result

