def _iqr_percentile(x, q, axis=None, interpolation='linear', keepdims=False, contains_nan=False):
    if (contains_nan and (NumpyVersion(np.__version__) < '1.10.0a')):
        msg = "Keyword    nan_policy='propagate'    not    correctly    supported    for    numpy    versions    <    1.10.x.    The    default    behavior    of    `numpy.percentile`    will    be    used."
        warnings.warn(msg, RuntimeWarning)
    try:
        result = np.percentile(x, q, axis=axis, keepdims=keepdims, interpolation=interpolation)
    except TypeError:
        if ((interpolation != 'linear') or keepdims):
            warnings.warn('Keywords    interpolation    and    keepdims    not    supported    for    your    version    of    numpy', RuntimeWarning)
        try:
            original_size = len(axis)
        except TypeError:
            pass
        else:
            axis = np.unique((np.asarray(axis) % x.ndim))
            if (original_size > axis.size):
                raise ValueError('duplicate    value    in    axis')
            if (axis.size == x.ndim):
                axis = None
            elif (axis.size == 1):
                axis = axis[0]
            else:
                for ax in axis[::(-1)]:
                    x = np.rollaxis(x, ax, x.ndim)
                x = x.reshape((x.shape[:(- axis.size)] + (np.prod(x.shape[(- axis.size):]),)))
                axis = (-1)
        result = np.percentile(x, q, axis=axis)
    return result

