            self.assertEqual(docker_utils.translate_input(**{item: 'foo'}), ({}, {item: "'foo'    is    not    a    dictionary"}, []))
        if (alias is not None):
            self.assertEqual(docker_utils.translate_input(**{name: 'foo', alias: 'bar'}), ({name: 'foo'}, {}, [name]))
        return func(self, *args, **kwargs)
    return wrapper

def cli(name, format='text', **kwargs):
    ret = {'name': name, 'changes': {}, 'result': True, 'comment': ''}
    ret['changes'] = __salt__['junos.cli'](name, format, **kwargs)
    return ret

def _max_cardinality_node(G, choices, wanna_connect):
    max_number = (-1)
    for x in choices:
        number = len([y for y in G[x] if (y in wanna_connect)])
        if (number > max_number):
            max_number = number
            max_cardinality_node = x
    return max_cardinality_node

def _add_billed_op_to_trace(trace, num_ops, op):
    if num_ops:
        billed_op = trace.add_billed_ops()
        billed_op.set_num_ops(num_ops)
        billed_op.set_op(op)

def adapt_references(subtree, destination_course_key, export_fs):
    subtree.runtime.export_fs = export_fs
    for (field_name, field) in subtree.fields.iteritems():
        if field.is_set_on(subtree):
            if isinstance(field, Reference):
                value = field.read_from(subtree)
                if (value is not None):
                    field.write_to(subtree, field.read_from(subtree).map_into_course(destination_course_key))
            elif (field_name == 'children'):
                [adapt_references(child, destination_course_key, export_fs) for child in subtree.get_children()]
            elif isinstance(field, ReferenceList):
                field.write_to(subtree, [ele.map_into_course(destination_course_key) for ele in field.read_from(subtree)])
            elif isinstance(field, ReferenceValueDict):
                field.write_to(subtree, {key: ele.map_into_course(destination_course_key) for (key, ele) in field.read_from(subtree).iteritems()})

def resolve_ssl_version(candidate):
    if (candidate is None):
        return PROTOCOL_SSLv23
    if isinstance(candidate, str):
        res = getattr(ssl, candidate, None)
        if (res is None):
            res = getattr(ssl, ('PROTOCOL_' + candidate))
        return res
    return candidate

def int_coercable(string):
    try:
        int(string)
        return True
    except ValueError:
        return False
